export * as Sheet from './sheet.tsx';
export type {
  BodyOwnProps as SheetBodyOwnProps,
  BodyProps as SheetBodyProps,
  CloseProps as SheetCloseProps,
  ContentOwnProps as SheetContentOwnProps,
  ContentProps as SheetContentProps,
  PopupOwnProps as SheetPopupOwnProps,
  PopupProps as SheetPopupProps,
  RootOwnProps as SheetRootOwnProps,
  RootProps as SheetRootProps,
  Side as SheetSide,
} from './sheet.tsx';

@layer hj.components {
  /*
   * Customise: --hj-sheet-inset (edge gap, 8px) · --hj-sheet-width · --hj-sheet-radius · --hj-sheet-scrim
   * Base UI drives: --drawer-swipe-movement-x/y, --drawer-swipe-progress, --drawer-swipe-strength,
   * --drawer-snap-point-offset.
   */
  .hj-sheet-backdrop {
    position: fixed;
    inset: 0;
    z-index: var(--hj-z-overlay);
    min-height: 100dvh;
    background: var(--hj-scrim);
    /*
     * The scrim follows the sheet: full (.55) when the sheet is fully up, lighter at a lower
     * detent (Base UI reports progress 1 there), thinning while it is swiped away.
     */
    opacity: calc(var(--hj-sheet-scrim, 0.55) * (1 - var(--drawer-swipe-progress, 0) * 0.6));
    transition: opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-sheet-backdrop[data-starting-style],
  .hj-sheet-backdrop[data-ending-style] {
    opacity: 0;
  }
  .hj-sheet-backdrop[data-swiping] {
    transition-duration: 0ms;
  }
  .hj-sheet-backdrop[data-ending-style] {
    transition-duration: calc(var(--drawer-swipe-strength, 1) * var(--hj-dur-base));
  }

  .hj-sheet-viewport {
    position: fixed;
    inset: 0;
    z-index: var(--hj-z-overlay);
    display: flex;
    padding: var(--hj-sheet-inset, 8px);
    padding-bottom: max(var(--hj-sheet-inset, 8px), env(safe-area-inset-bottom, 0px));
    touch-action: none;
  }
  .hj-sheet-viewport[data-side='bottom'] {
    align-items: flex-end;
    justify-content: center;
  }
  .hj-sheet-viewport[data-side='top'] {
    align-items: flex-start;
    justify-content: center;
  }
  .hj-sheet-viewport[data-side='right'] {
    justify-content: flex-end;
  }
  .hj-sheet-viewport[data-side='left'] {
    justify-content: flex-start;
  }

  .hj-sheet-popup {
    --_inset: var(--hj-sheet-inset, 8px);
    position: relative;
    display: flex;
    flex-direction: column;
    max-height: calc(100dvh - var(--_inset) * 2);
    overflow: hidden;
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-sheet-radius, var(--hj-radius-xl));
    background: var(--hj-surface-2);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    touch-action: none;
    will-change: transform;
    /* arrivals settle on gentle; the finger owns it while swiping */
    transition:
      transform var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle),
      opacity var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-sheet-popup[data-swiping] {
    transition-duration: 0ms;
  }
  .hj-sheet-popup[data-ending-style] {
    transition-duration: calc(var(--drawer-swipe-strength, 1) * var(--hj-dur-base));
    transition-timing-function: var(--hj-ease-out);
  }
  /* reduced motion: --hj-travel is 0, so the slide collapses and only the fade remains */
  .hj-sheet-popup[data-starting-style],
  .hj-sheet-popup[data-ending-style] {
    opacity: var(--hj-travel);
  }

  .hj-sheet-popup[data-side='bottom'],
  .hj-sheet-popup[data-side='top'] {
    width: 100%;
    max-width: var(--hj-sheet-width, 560px);
  }
  .hj-sheet-popup[data-side='bottom'][data-size='sm'],
  .hj-sheet-popup[data-side='top'][data-size='sm'] {
    max-width: var(--hj-sheet-width, 420px);
  }
  .hj-sheet-popup[data-side='bottom'][data-size='lg'],
  .hj-sheet-popup[data-side='top'][data-size='lg'] {
    max-width: var(--hj-sheet-width, 720px);
  }
  .hj-sheet-popup[data-side='bottom'] {
    transform: translateY(
      calc(var(--drawer-snap-point-offset, 0px) + var(--drawer-swipe-movement-y, 0px))
    );
  }
  .hj-sheet-popup[data-side='bottom'][data-starting-style],
  .hj-sheet-popup[data-side='bottom'][data-ending-style] {
    transform: translateY(calc((100% + var(--_inset) + 2px) * var(--hj-travel)));
  }
  .hj-sheet-popup[data-side='top'] {
    transform: translateY(var(--drawer-swipe-movement-y, 0px));
  }
  .hj-sheet-popup[data-side='top'][data-starting-style],
  .hj-sheet-popup[data-side='top'][data-ending-style] {
    transform: translateY(calc((-100% - var(--_inset) - 2px) * var(--hj-travel)));
  }

  .hj-sheet-popup[data-side='right'],
  .hj-sheet-popup[data-side='left'] {
    width: min(var(--hj-sheet-width, 400px), 100%);
    height: 100%;
    max-height: none;
    transform: translateX(var(--drawer-swipe-movement-x, 0px));
  }
  .hj-sheet-popup[data-side='right'][data-size='sm'],
  .hj-sheet-popup[data-side='left'][data-size='sm'] {
    width: min(var(--hj-sheet-width, 320px), 100%);
  }
  .hj-sheet-popup[data-side='right'][data-size='lg'],
  .hj-sheet-popup[data-side='left'][data-size='lg'] {
    width: min(var(--hj-sheet-width, 520px), 100%);
  }
  .hj-sheet-popup[data-side='right'][data-starting-style],
  .hj-sheet-popup[data-side='right'][data-ending-style] {
    transform: translateX(calc((100% + var(--_inset) + 2px) * var(--hj-travel)));
  }
  .hj-sheet-popup[data-side='left'][data-starting-style],
  .hj-sheet-popup[data-side='left'][data-ending-style] {
    transform: translateX(calc((-100% - var(--_inset) - 2px) * var(--hj-travel)));
  }

  .hj-sheet-handle {
    flex: none;
    width: 36px;
    height: 4px;
    margin: 8px auto 2px;
    border-radius: var(--hj-radius-pill);
    background: color-mix(in srgb, var(--hj-fg) 20%, transparent);
  }

  .hj-sheet-header {
    position: relative;
    flex: none;
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 14px 56px 8px 20px;
  }
  .hj-sheet-title {
    margin: 0;
    font: var(--hj-type-title);
    letter-spacing: var(--hj-tracking-title);
  }
  .hj-sheet-description {
    margin: 0;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--hj-fg-dim);
  }

  .hj-sheet-body {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    touch-action: pan-y;
    padding: 4px 20px 20px;
  }
  .hj-sheet-body[data-pending] {
    overflow: hidden;
  }
  .hj-sheet-placeholder {
    display: block;
    padding-top: 8px;
  }
  .hj-sheet-placeholder > i {
    display: block;
    height: 12px;
    margin: 0 0 14px;
    border-radius: var(--hj-radius-pill);
    background: color-mix(in srgb, var(--hj-fg) 7%, transparent);
  }
  .hj-sheet-placeholder > i:nth-child(2) {
    width: 72%;
  }
  .hj-sheet-placeholder > i:nth-child(3) {
    width: 48%;
  }

  .hj-sheet-footer {
    flex: none;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 8px;
    padding: 12px 20px 16px;
    border-top: 1px solid var(--hj-line);
  }

  .hj-sheet-close[data-icon] {
    position: absolute;
    top: 12px;
    right: 12px;
    display: grid;
    place-items: center;
    width: 32px;
    height: 32px;
    padding: 0;
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg-dim);
    line-height: 0;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-sheet-close[data-icon]::before {
    content: '';
    position: absolute;
    inset: -6px;
  }
  .hj-sheet-close[data-icon]:hover {
    background: color-mix(in srgb, var(--hj-fg) 10%, transparent);
    color: var(--hj-fg);
  }
  .hj-sheet-close[data-icon]:active {
    transform: scale(0.92);
    transition-duration: 70ms;
  }
  .hj-sheet-close[data-icon] svg {
    width: 16px;
    height: 16px;
  }

  .hj-sheet-swipe-area {
    position: fixed;
    z-index: var(--hj-z-sticky);
  }
}

'use client';
import { Drawer as Base } from '@base-ui/react/drawer';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export type Side = 'bottom' | 'top' | 'left' | 'right';
const SWIPE: Readonly<Record<Side, 'down' | 'up' | 'left' | 'right'>> = {
  bottom: 'down',
  top: 'up',
  left: 'left',
  right: 'right',
};

interface SheetState {
  side: Side;
  /** The entrance has finished; heavy content may mount. */
  entered: boolean;
}
const SheetContext = React.createContext<SheetState>({ side: 'bottom', entered: true });

export interface RootOwnProps {
  /** Edge the sheet lives on; swiping toward it dismisses. @default 'bottom' */
  side?: Side;
}
export interface RootProps extends RootOwnProps, Omit<Base.Root.Props, 'swipeDirection'> {}

/** State owner: open, snap points (detents), modal. Swipe to dismiss comes with it. */
export function Root(props: RootProps): React.ReactElement {
  const { side = 'bottom', onOpenChange, onOpenChangeComplete, ...rest } = props;
  const [entered, setEntered] = React.useState(false);
  const ctx = React.useMemo<SheetState>(() => ({ side, entered }), [side, entered]);
  return (
    <SheetContext.Provider value={ctx}>
      <Base.Root
        {...rest}
        swipeDirection={SWIPE[side]}
        onOpenChange={(open, details) => {
          if (!open) setEntered(false);
          onOpenChange?.(open, details);
        }}
        onOpenChangeComplete={(open) => {
          setEntered(open);
          onOpenChangeComplete?.(open);
        }}
      />
    </SheetContext.Provider>
  );
}

export const Trigger: HanjiPart<typeof Base.Trigger> = part(
  Base.Trigger,
  'Sheet.Trigger',
  'hj-sheet-trigger',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'Sheet.Backdrop',
  'hj-sheet-backdrop',
);
export const Title: HanjiPart<typeof Base.Title> = part(
  Base.Title,
  'Sheet.Title',
  'hj-sheet-title',
);
export const Description: HanjiPart<typeof Base.Description> = part(
  Base.Description,
  'Sheet.Description',
  'hj-sheet-description',
);
/** An edge strip that opens the sheet with a swipe (for side sheets on touch). */
export const SwipeArea: HanjiPart<typeof Base.SwipeArea> = part(
  Base.SwipeArea,
  'Sheet.SwipeArea',
  'hj-sheet-swipe-area',
);
/** The grab bar. Decorative: the whole sheet can be swiped. */
export const Handle: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Sheet.Handle',
  'hj-sheet-handle',
);
/** Title row: title, description and the corner ✕. */
export const Header: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Sheet.Header',
  'hj-sheet-header',
);
/** Pinned action row at the bottom of the sheet. */
export const Footer: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Sheet.Footer',
  'hj-sheet-footer',
);
export const createHandle: typeof Base.createHandle = Base.createHandle;

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

/** Lays the sheet against its edge, 8px in (hanji edge inset). */
export function Viewport(props: Base.Viewport.Props): React.ReactElement {
  const config = useHanjiConfig();
  const { side } = React.useContext(SheetContext);
  const { className, ...rest } = withDefaults(config, 'Sheet.Viewport', props);
  return (
    <Base.Viewport
      {...rest}
      data-side={side}
      className={cls(config, 'Sheet.Viewport', 'hj-sheet-viewport', className)}
    />
  );
}

export interface PopupOwnProps {
  /** Width of side sheets (sm 320, md 400, lg 520) or max width of bottom/top sheets (sm 420, md 560, lg 720). */
  size?: 'sm' | 'md' | 'lg';
}
export interface PopupProps extends PopupOwnProps, Base.Popup.Props {}

/** The sheet: surface-2, hairline, radius xl. Follows the finger, settles on gentle. */
export function Popup(props: PopupProps): React.ReactElement {
  const config = useHanjiConfig();
  const { side } = React.useContext(SheetContext);
  const { size = 'md', className, ...rest } = withDefaults(config, 'Sheet.Popup', props);
  return (
    <Base.Popup
      {...rest}
      data-side={side}
      data-size={size}
      className={cls(config, 'Sheet.Popup', 'hj-sheet-popup', className)}
    />
  );
}

export interface BodyOwnProps {
  /**
   * Mount children only after the entrance has landed, holding the room with quiet lines.
   * Use for heavy lists: mounting during an entrance is a jerk (hanji PRINCIPLES §12).
   */
  defer?: boolean;
  /** What to show while deferred. Defaults to three quiet lines. */
  placeholder?: React.ReactNode;
}
export interface BodyProps extends BodyOwnProps, Base.Content.Props {}

/** The scrolling content area. */
export function Body(props: BodyProps): React.ReactElement {
  const config = useHanjiConfig();
  const { entered } = React.useContext(SheetContext);
  const {
    defer = false,
    placeholder,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Sheet.Body', props);
  const show = !defer || entered;
  return (
    <Base.Content
      {...rest}
      data-pending={flag(!show)}
      aria-busy={show ? undefined : true}
      className={cls(config, 'Sheet.Body', 'hj-sheet-body', className)}
    >
      {show
        ? children
        : (placeholder ?? (
            <span
              className={config.unstyled ? undefined : 'hj-sheet-placeholder'}
              aria-hidden="true"
            >
              <i />
              <i />
              <i />
            </span>
          ))}
    </Base.Content>
  );
}

export interface CloseOwnProps {
  /** Render the corner ✕ icon button. Defaults to true when the Close has no children. */
  icon?: boolean;
}
export interface CloseProps extends CloseOwnProps, Base.Close.Props {}

/** Closes. With no children it renders the corner ✕ with an accessible label. */
export function Close(props: CloseProps): React.ReactElement {
  const config = useHanjiConfig();
  const { icon, className, children, ...rest } = withDefaults(config, 'Sheet.Close', props);
  const asIcon = icon ?? children === undefined;
  return (
    <Base.Close
      aria-label={asIcon ? config.strings.close : undefined}
      {...rest}
      data-icon={flag(asIcon)}
      className={cls(config, 'Sheet.Close', 'hj-sheet-close', className)}
    >
      {asIcon ? config.icons.x : children}
    </Base.Close>
  );
}

export interface ContentOwnProps {
  /** Draw the scrim. @default true */
  backdrop?: boolean;
  /** Draw the grab bar. @default true for bottom and top sheets */
  handle?: boolean;
  container?: Base.Portal.Props['container'];
  keepMounted?: boolean;
}
export interface ContentProps extends ContentOwnProps, PopupProps {}

/** Shorthand for Portal + Backdrop + Viewport + Popup (+ Handle). */
export function Content(props: ContentProps): React.ReactElement {
  const config = useHanjiConfig();
  const { side } = React.useContext(SheetContext);
  const {
    backdrop = true,
    handle,
    container,
    keepMounted,
    children,
    ...popup
  } = withDefaults(config, 'Sheet.Content', props);
  const showHandle = handle ?? (side === 'bottom' || side === 'top');
  return (
    <Portal container={container} keepMounted={keepMounted}>
      {backdrop ? <Backdrop /> : null}
      <Viewport>
        <Popup {...popup}>
          {showHandle && side === 'bottom' ? <Handle aria-hidden="true" /> : null}
          {children}
          {showHandle && side === 'top' ? <Handle aria-hidden="true" /> : null}
        </Popup>
      </Viewport>
    </Portal>
  );
}
